function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 3 || arr.length > 50000) return 'arr needs 3 to 5 * 10^4 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value is an integer between -10^4 and 10^4.';
  return null;
}

