function canThreePartsEqualSum(arr) {
  let total = 0;
  for (const value of arr) {
    total += value;
  }
  if (total % 3 !== 0) {
    return false;
  }

  const target = total / 3;
  let prefix = 0;
  let cuts = 0;
  for (let i = 0; i < arr.length - 1; i++) {
    prefix += arr[i];
    if (prefix === (cuts + 1) * target) {
      cuts++;
    }
    if (cuts === 2) {
      return true;
    }
  }
  return false;
}

