function canThreePartsEqualSum(arr) {
  // Try every pair of cut positions and add each piece up from scratch.
  const n = arr.length;
  const add = (from, to) => { let s = 0; for (let k = from; k < to; k++) s += arr[k]; return s; };
  for (let i = 0; i < n; i++) {
    for (let j = i + 2; j < n; j++) {
      const a = add(0, i + 1), b = add(i + 1, j), c = add(j, n);
      if (a === b && b === c) return true;
    }
  }
  return false;
}

