function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const limit = 10000;
  const large = size === 'large';
  const n = large ? 2000 : int(3, 10);
  const span = large ? (rand() < 0.5 ? 50 : limit) : (rand() < 0.7 ? 3 : 20);
  const arr = Array.from({ length: n }, () => int(-span, span));
  if (rand() < 0.5) return [arr];
  // Otherwise make the answer true: choose two cuts and adjust each piece until it reaches the same total.
  const first = int(1, n - 2);
  const second = int(first + 1, n - 1);
  const pieces = [[0, first], [first, second], [second, n]];
  const goal = int(-3 * span, 3 * span);
  for (const [from, to] of pieces) {
    let diff = goal;
    for (let k = from; k < to; k++) diff -= arr[k];
    for (let k = from; k < to && diff !== 0; k++) {
      const change = Math.max(-limit - arr[k], Math.min(limit - arr[k], diff));
      arr[k] += change;
      diff -= change;
    }
    if (diff !== 0) return [Array.from({ length: n }, () => int(-span, span))];
  }
  return [arr];
}
